@ResourceLock(Resources.SYSTEM_PROPERTIES)
class NativePrimitiveNullExpressionDomainTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI S = VF.createIRI("urn:null-expression:s"), A = VF.createIRI("urn:null-expression:a"),
			P = VF.createIRI("urn:null-expression:p"), Q = VF.createIRI("urn:null-expression:q"),
			O = VF.createIRI("urn:null-expression:o"), HIT = VF.createIRI("urn:null-expression:hit"),
			MISS = VF.createIRI("urn:null-expression:miss"), OLD = VF.createIRI("urn:null-expression:old");
	private static final String FACTORS = "rdf4j.lmdb.factor.transport.enabled";

	static Stream<Arguments> cases() {
		return Stream.of(false, true)
				.flatMap(factors -> Stream.of("ABSENT", "NULL", "HIT", "MISS")
						.flatMap(marker -> Stream.of(false, true)
								.flatMap(target -> Stream.of("STATEMENT_WRITE", "BIND_WRITE")
										.map(suffix -> Arguments.of(factors, marker, target, suffix)))));
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void freshSingleAssignmentKeepsTheNativeAggregatePath(boolean summary) {
		var source = new LmdbNativeRepeatedStatementTermRoleTest.MemorySource(List.of(
				VF.createStatement(S, P, O), VF.createStatement(A, Q, HIT)), OLD);
		StatementPattern first = new StatementPattern(Var.of("seed"), Var.of("fixedP", P, true, true),
				Var.of("fixedO", O, true, true));
		Group group = new Group(new Extension(first, new ExtensionElem(Var.of("marker"), "copy")));
		group.addGroupBindingName("seed");
		group.addGroupElement(new GroupElem("n", new Count(Var.of("copy"))));
		QueryBindingSet bindings = new QueryBindingSet();
		bindings.setBinding("marker", HIT);
		var context = new QueryEvaluationContext.Minimal((Dataset) null);
		List<org.eclipse.rdf4j.query.BindingSet> expected;
		try (var rows = new DefaultEvaluationStrategy(source, null)
				.precompileRuntimeSubtree(group.clone(), context)
				.evaluate(bindings)) {
			expected = QueryResults.asList(rows);
		}
		assertEquals(1, expected.size());
		assertEquals(S, expected.getFirst().getValue("seed"));
		assertEquals(1L, ((org.eclipse.rdf4j.model.Literal) expected.getFirst().getValue("n")).longValue());
		group.setExecutionSummaryEnabled(summary);
		var strategy = new LmdbNativeEvaluationStrategy(source, null, null, 0L, new EvaluationStatistics(), false)
				.forWorker(source);
		var compiled = LmdbNativeAggregateCompiler.tryCompile(group, context, strategy, source);
		assertNotNull(compiled);
		assertTrue(((LmdbNativePhysicalPlan) compiled).nativePhysicalPlan().contains("Extension(copies="));
		try (var rows = compiled.evaluate(bindings)) {
			assertEquals(expected, QueryResults.asList(rows));
		}
		if (summary) {
			String path = group.getStringMetricActual("nativeExecutionPath");
			assertNotNull(path, "same executed Group owns its actual-path receipt");
			assertTrue(!path.contains("generic"), "fresh single-assignment input remains native: " + path);
		}
		assertEquals(source.opened, source.closed);
	}

	@ParameterizedTest(name = "factors={0}, marker={1}, target occupied={2}, suffix={3}")
	@MethodSource("cases")
	void aPrimitiveVarReadCannotMintANullMappingOrBlockALaterWriter(boolean factors, String marker, boolean occupied,
			String suffix) {
		String previous = System.getProperty(FACTORS);
		System.setProperty(FACTORS, factors ? "true" : "false");
		var source = new LmdbNativeRepeatedStatementTermRoleTest.MemorySource(
				List.of(VF.createStatement(S, P, O), VF.createStatement(A, Q, HIT)), OLD);
		try {
			StatementPattern first = new StatementPattern(Var.of("seed"), Var.of("fixedP", P, true, true),
					Var.of("fixedO", O, true, true));
			Extension copy = new Extension(first, new ExtensionElem(Var.of("marker"), "copy"));
			TupleExpr input = suffix.equals("STATEMENT_WRITE") ? new Join(copy,
					new StatementPattern(Var.of("fixedA", A, true, true), Var.of("fixedQ", Q, true, true),
							Var.of("copy")))
					: new Extension(copy, new ExtensionElem(new ValueConstant(HIT), "copy"));
			Group group = new Group(input);
			group.addGroupElement(new GroupElem("n", new Count(null)));
			QueryBindingSet bindings = new QueryBindingSet();
			if (marker.equals("NULL")) {
				bindings.setBinding("marker", null);
			} else if (!marker.equals("ABSENT")) {
				bindings.setBinding("marker", marker.equals("HIT") ? HIT : MISS);
			}
			if (occupied) {
				bindings.setBinding("copy", OLD);
			}
			var context = new QueryEvaluationContext.Minimal((Dataset) null);
			var ordinary = new DefaultEvaluationStrategy(source, null);
			List<org.eclipse.rdf4j.query.BindingSet> expected;
			try (var rows = ordinary.precompileRuntimeSubtree(group.clone(), context).evaluate(bindings)) {
				expected = QueryResults.asList(rows);
			}
			assertEquals(1, expected.size());
			long expectedCount = suffix.equals("STATEMENT_WRITE") && marker.equals("MISS") ? 0L : 1L;
			assertEquals(expectedCount,
					((org.eclipse.rdf4j.model.Literal) expected.getFirst().getValue("n")).longValue(),
					"ordinary Extension removes failed targets and a subsequent actual writer may bind them");
			var strategy = new LmdbNativeEvaluationStrategy(source, null, null, 0L, new EvaluationStatistics(), false)
					.forWorker(source);
			var compiled = LmdbNativeAggregateCompiler.tryCompile(group, context, strategy, source);
			assertNotNull(compiled, "the aggregate consumer is the normal owning primitive input route");
			assertTrue(compiled instanceof LmdbNativePhysicalPlan);
			String plan = ((LmdbNativePhysicalPlan) compiled).nativePhysicalPlan();
			assertTrue(plan.contains("Extension(copies="),
					"actual primitive CopyBinding plan required before a semantic claim: " + plan);
			try (var rows = compiled.evaluate(bindings)) {
				assertEquals(expected, QueryResults.asList(rows), plan);
			}
			assertEquals(source.opened, source.closed);
		} finally {
			if (previous == null) {
				System.clearProperty(FACTORS);
			} else {
				System.setProperty(FACTORS, previous);
			}
		}
	}
}
